(() => {
'use strict';
const canvas = document.getElementById('c');
const ctx = canvas.getContext('2d');
const mq = matchMedia('(prefers-reduced-motion: reduce)');
let reduced = mq.matches;

let W = 0, H = 0, DPR = 1, base = 0;
const S = {};   // scene geometry
const L = {};   // pre-rendered static layers
const TAU = Math.PI * 2;

function mulberry32(a){ return function(){ a |= 0; a = a + 0x6D2B79F5 | 0; let t = Math.imul(a ^ a >>> 15, 1 | a); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; }; }
let rng = mulberry32(1337);
const rnd = (a = 0, b = 1) => a + (b - a) * rng();
const lerp = (a, b, t) => a + (b - a) * t;
const clamp = (v, a, b) => v < a ? a : v > b ? b : v;

const NP = new Float32Array(256); { const r = mulberry32(99); for (let i = 0; i < 256; i++) NP[i] = r(); }
function noise(t){ const i = Math.floor(t), f = t - i, a = NP[i & 255], b = NP[(i + 1) & 255]; return a + (b - a) * f * f * (3 - 2 * f); }

function mkLayer(){ const c = document.createElement('canvas'); c.width = W * DPR; c.height = H * DPR; const g = c.getContext('2d'); g.scale(DPR, DPR); return { c, g }; }
function ell(g, x, y, rx, ry){ g.beginPath(); g.ellipse(x, y, rx, ry, 0, 0, TAU); }
function inEll(g, x, y, rx, ry, fn){ g.save(); g.translate(x, y); g.scale(1, ry / rx); fn(rx); g.restore(); }
function softDisc(g, x, y, rx, ry, stops){ inEll(g, x, y, rx, ry, (r) => { const grd = g.createRadialGradient(0, 0, 0, 0, 0, r); stops.forEach(s => grd.addColorStop(s[0], s[1])); g.fillStyle = grd; g.beginPath(); g.arc(0, 0, r, 0, TAU); g.fill(); }); }

function layout(){
  W = innerWidth; H = innerHeight; DPR = Math.min(devicePixelRatio || 1, 2);
  canvas.width = W * DPR; canvas.height = H * DPR;
  canvas.style.width = W + 'px'; canvas.style.height = H + 'px';
  base = Math.min(W, H * 1.15);
  S.cx = W / 2; S.cy = H * 0.56;
  S.rx = base * 0.36; S.ry = S.rx * 0.42; S.depth = S.rx * 0.6;
  S.irx = S.rx * 0.94; S.iry = S.ry * 0.92;                      // inner rim
  S.bx = S.cx; S.by = S.cy + S.ry * 0.14; S.brx = S.rx * 0.905; S.bry = S.ry * 0.86; // broth surface
