  for (let i = 0; i < 120; i++){
    const y0 = hy + Math.pow(rnd(), 0.7) * (H - hy);
    const amp = rnd(2, 9), ph = rnd(0, TAU), fr = rnd(0.002, 0.006), dark = rng() < 0.5;
    g.strokeStyle = dark ? `rgba(0,0,0,${rnd(0.08, 0.25)})` : `rgba(130,85,45,${rnd(0.04, 0.12)})`;
    g.lineWidth = rnd(0.6, 2.2);
    g.beginPath();
    for (let x = -10; x <= W + 10; x += 12){ const y = y0 + Math.sin(x * fr + ph) * amp + Math.sin(x * fr * 3.1 + ph * 2) * amp * 0.3; x === -10 ? g.moveTo(x, y) : g.lineTo(x, y); }
    g.stroke();
  }
  g.restore();
  grd = g.createRadialGradient(cx - rx * 0.3, cy, 0, cx - rx * 0.3, cy, base * 0.95);
  grd.addColorStop(0, 'rgba(190,110,45,0.45)'); grd.addColorStop(0.45, 'rgba(120,60,20,0.18)'); grd.addColorStop(1, 'rgba(0,0,0,0)');
  g.fillStyle = grd; g.fillRect(0, 0, W, H);
  softDisc(g, cx + rx * 0.18, cy + depth * 0.8, rx * 1.45, rx * 1.45 * 0.38, [[0, 'rgba(0,0,0,0.85)'], [0.5, 'rgba(0,0,0,0.5)'], [1, 'rgba(0,0,0,0)']]);
}

function drawBowl(g){
  const { cx, cy, rx, ry, depth, irx, iry, bx, by, brx, bry } = S;
  g.beginPath();
  g.moveTo(cx - rx, cy);
  g.bezierCurveTo(cx - rx, cy + depth * 0.62, cx - rx * 0.78, cy + depth, cx - rx * 0.42, cy + depth);
