  grd.addColorStop(0, 'rgba(255,220,190,0.10)'); grd.addColorStop(0.5, 'rgba(0,0,0,0.15)'); grd.addColorStop(1, 'rgba(0,0,0,0.65)');
  g.fillStyle = grd; g.fillRect(cx - rx, cy, rx * 2, depth + ry);
  grd = g.createLinearGradient(0, cy, 0, cy + ry * 1.4);
  grd.addColorStop(0, 'rgba(130,105,95,0.35)'); grd.addColorStop(1, 'rgba(130,105,95,0)');
  g.fillStyle = grd; g.fillRect(cx - rx, cy, rx * 2, ry * 1.4);
  for (let i = 0; i < 600; i++){
    const x = rnd(cx - rx, cx + rx), y = rnd(cy, cy + depth + ry * 0.3);
    g.fillStyle = rng() < 0.5 ? `rgba(0,0,0,${rnd(0.1, 0.35)})` : `rgba(230,210,190,${rnd(0.05, 0.2)})`;
    g.beginPath(); g.arc(x, y, rnd(0.4, 1.4), 0, TAU); g.fill();
  }
  g.strokeStyle = 'rgba(255,225,190,0.22)'; g.lineWidth = rx * 0.02; g.lineCap = 'round';
  g.beginPath(); g.moveTo(cx - rx * 0.985, cy + ry * 0.1); g.bezierCurveTo(cx - rx * 0.99, cy + depth * 0.6, cx - rx * 0.8, cy + depth * 0.95, cx - rx * 0.5, cy + depth * 0.98); g.stroke();
  g.restore();
  ell(g, cx, cy, rx, ry);
  grd = g.createLinearGradient(cx - rx, cy - ry, cx + rx, cy + ry);
  grd.addColorStop(0, '#8d8074'); grd.addColorStop(0.4, '#5d544c'); grd.addColorStop(1, '#2b2624');
  g.fillStyle = grd; g.fill();
  g.strokeStyle = 'rgba(255,235,210,0.35)'; g.lineWidth = 1; g.stroke();
  ell(g, cx, cy, irx, iry);
  grd = g.createLinearGradient(0, cy - iry, 0, cy + iry);
  grd.addColorStop(0, '#0d0a09'); grd.addColorStop(0.5, '#2b221d'); grd.addColorStop(1, '#3d2f26');
  g.fillStyle = grd; g.fill();
  g.save(); ell(g, cx, cy, irx, iry); g.clip();
  softDisc(g, bx, by, brx, bry, [[0, '#e2a54a'], [0.35, '#c9832f'], [0.75, '#9a5a1e'], [1, '#673812']]);
  g.save(); ell(g, bx, by, brx, bry); g.clip();
  g.strokeStyle = 'rgba(255,215,140,0.15)'; g.lineWidth = brx * 0.03; g.lineCap = 'round';
  for (let i = 0; i < 16; i++){
    const a = rnd(0, TAU), r = rnd(0.2, 0.85), x = bx + Math.cos(a) * brx * r, y = by + Math.sin(a) * bry * r;
    g.beginPath(); g.moveTo(x, y);
    g.bezierCurveTo(x + rnd(-1, 1) * brx * 0.3, y + rnd(-1, 1) * bry * 0.3, x + rnd(-1, 1) * brx * 0.4, y + rnd(-1, 1) * bry * 0.4, x + rnd(-1, 1) * brx * 0.5, y + rnd(-1, 1) * bry * 0.5);
    g.stroke();
  }
  grd = g.createLinearGradient(0, by - bry, 0, by - bry * 0.3);
  grd.addColorStop(0, 'rgba(40,15,0,0.7)'); grd.addColorStop(1, 'rgba(40,15,0,0)');
  g.fillStyle = grd; g.fillRect(bx - brx, by - bry, brx * 2, bry * 0.7);
  inEll(g, bx, by, brx, bry, (r) => { const e = g.createRadialGradient(0, 0, r * 0.78, 0, 0, r); e.addColorStop(0, 'rgba(60,25,5,0)'); e.addColorStop(1, 'rgba(60,25,5,0.55)'); g.fillStyle = e; g.beginPath(); g.arc(0, 0, r, 0, TAU); g.fill(); });
  g.restore();
  g.restore();
}
