function shadow(g, on){ if (on){ g.shadowColor = 'rgba(40,15,0,0.55)'; g.shadowBlur = S.rx * 0.03; g.shadowOffsetX = S.rx * 0.008; g.shadowOffsetY = S.rx * 0.014; } else { g.shadowColor = 'rgba(0,0,0,0)'; g.shadowBlur = 0; g.shadowOffsetX = 0; g.shadowOffsetY = 0; } }

function drawFood(g){
  const { bx, by, brx, bry, cx, cy, irx, iry } = S;
  const P = (u, v) => [bx + u * brx, by + v * bry];
  g.lineJoin = 'round'; g.lineCap = 'round';
  nori(g, ...P(-0.62, -0.40), brx * 0.26, bry * 1.5, -0.12);
  nori(g, ...P(-0.40, -0.54), brx * 0.24, bry * 1.45, 0.08);
  shadow(g, true);
  bokchoy(g, P(0.45, -0.42), brx * 0.36);
  g.save(); ell(g, cx, cy, irx, iry); g.clip();
  shiitake(g, ...P(0.58, -0.10), brx * 0.15, -0.2);
  shiitake(g, ...P(0.50, 0.30), brx * 0.12, 0.35);
  shadow(g, false);
  noodles(g);
  shadow(g, true);
  tofu(g, ...P(-0.56, 0.28), brx * 0.15, 0.15);
  tofu(g, ...P(-0.30, 0.50), brx * 0.15, -0.2);
  tofu(g, ...P(-0.60, 0.56), brx * 0.14, 0.05);
  tofu(g, ...P(-0.06, 0.66), brx * 0.14, 0.3);
  corn(g, P(0.24, 0.55), brx * 0.2, bry * 0.18);
  scallions(g);
  shadow(g, false);
  sesame(g); chili(g);
  g.restore();
  chopsticks(g);
}

function nori(g, x, y, w, h, tilt){
  g.save();
  g.beginPath();
  g.moveTo(x - w / 2, y + h * 0.04);
  g.lineTo(x + w / 2, y);
  g.quadraticCurveTo(x + w / 2 + tilt * h * 0.5, y - h * 0.55, x + w / 2 + tilt * h, y - h);
  g.quadraticCurveTo(x + tilt * h, y - h * 1.08, x - w / 2 + tilt * h, y - h * 0.94);
  g.closePath();
  const grd = g.createLinearGradient(x - w / 2, 0, x + w / 2, 0);
  grd.addColorStop(0, '#0b1410'); grd.addColorStop(0.45, '#203729'); grd.addColorStop(0.6, '#15271a'); grd.addColorStop(1, '#08100c');
  g.fillStyle = grd; g.fill();
  g.clip();
  g.strokeStyle = 'rgba(150,190,150,0.10)'; g.lineWidth = 0.8;
  for (let i = 0; i < 10; i++){ const yy = y - h * rnd(0.05, 0.95); g.beginPath(); g.moveTo(x - w, yy); g.lineTo(x + w, yy + rnd(-3, 3)); g.stroke(); }
  g.strokeStyle = 'rgba(255,255,255,0.12)'; g.lineWidth = 1.2;
  g.beginPath(); g.moveTo(x - w * 0.1 + tilt * h * 0.2, y - h * 0.2); g.lineTo(x - w * 0.05 + tilt * h * 0.9, y - h * 0.9); g.stroke();
  g.restore();
}

function bokchoy(g, [x, y], s){
  const n = 5;
  for (let i = 0; i < n; i++){
    const a = -Math.PI / 2 + (i - (n - 1) / 2) * 0.38 + rnd(-0.08, 0.08);
    const len = s * rnd(0.8, 1.15);
    const tx = x + Math.cos(a) * len, ty = y + Math.sin(a) * len * 0.85;
    g.beginPath(); g.moveTo(x - s * 0.07, y);
    g.quadraticCurveTo(x + Math.cos(a) * len * 0.5 - s * 0.08, y + Math.sin(a) * len * 0.45, tx - s * 0.06, ty);
    g.lineTo(tx + s * 0.06, ty);
    g.quadraticCurveTo(x + Math.cos(a) * len * 0.5 + s * 0.08, y + Math.sin(a) * len * 0.45, x + s * 0.07, y);
    g.closePath();
    let grd = g.createLinearGradient(x, y, tx, ty); grd.addColorStop(0, '#eef5e2'); grd.addColorStop(1, '#c9e2b0');
    g.fillStyle = grd; g.fill(); g.strokeStyle = 'rgba(60,110,50,0.35)'; g.lineWidth = 0.8; g.stroke();
    const lw = s * rnd(0.28, 0.38), lh = s * rnd(0.45, 0.6);
    g.save(); g.translate(tx, ty); g.rotate(a + Math.PI / 2);
    g.beginPath(); g.moveTo(0, 0.15 * lh);
    g.bezierCurveTo(-lw * 1.2, -lh * 0.1, -lw * 1.1, -lh * 0.9, 0, -lh);
    g.bezierCurveTo(lw * 1.1, -lh * 0.9, lw * 1.2, -lh * 0.1, 0, 0.15 * lh);
    grd = g.createLinearGradient(0, 0, 0, -lh); grd.addColorStop(0, '#54a343'); grd.addColorStop(1, '#2c6a2a');
    g.fillStyle = grd; g.fill(); g.strokeStyle = 'rgba(20,50,20,0.5)'; g.lineWidth = 0.8; g.stroke();
    g.strokeStyle = 'rgba(200,235,170,0.5)'; g.lineWidth = 1;
    g.beginPath(); g.moveTo(0, 0.1 * lh); g.lineTo(0, -lh * 0.9); g.stroke();
    for (let k = 1; k < 4; k++){ const yy = -lh * k / 4.5; g.beginPath(); g.moveTo(0, yy); g.lineTo(-lw * 0.6, yy - lh * 0.15); g.moveTo(0, yy); g.lineTo(lw * 0.6, yy - lh * 0.15); g.stroke(); }
    g.restore();
  }
}

function shiitake(g, x, y, r, rot){
  g.save(); g.translate(x, y); g.rotate(rot);
  g.beginPath(); g.ellipse(0, 0, r, r * 0.72, 0, 0, TAU);
  const grd = g.createRadialGradient(-r * 0.3, -r * 0.3, r * 0.1, 0, 0, r * 1.1);
  grd.addColorStop(0, '#8d5f3c'); grd.addColorStop(0.6, '#5b3820'); grd.addColorStop(1, '#2e1a0e');
  g.fillStyle = grd; g.fill();
  g.strokeStyle = 'rgba(20,10,5,0.6)'; g.lineWidth = 1; g.stroke();
  const sb = g.shadowBlur; shadow(g, false);
  for (let k = 0; k < 3; k++){
    const a = k * Math.PI / 3 + 0.3, dx = Math.cos(a) * r * 0.55, dy = Math.sin(a) * r * 0.4;
    g.strokeStyle = 'rgba(60,30,10,0.7)'; g.lineWidth = r * 0.14; g.beginPath(); g.moveTo(dx + 1, dy + 1.2); g.lineTo(-dx + 1, -dy + 1.2); g.stroke();
    g.strokeStyle = 'rgba(238,220,185,0.9)'; g.lineWidth = r * 0.09; g.beginPath(); g.moveTo(dx, dy); g.lineTo(-dx, -dy); g.stroke();
  }
  g.strokeStyle = 'rgba(255,220,180,0.25)'; g.lineWidth = 1.5;
  g.beginPath(); g.ellipse(0, 0, r * 0.9, r * 0.62, 0, Math.PI * 1.1, Math.PI * 1.9); g.stroke();
  if (sb) shadow(g, true);
  g.restore();
}

function noodles(g){
  const { bx, by, brx, bry } = S;
  const nx = bx - brx * 0.08, ny = by + bry * 0.02, nrx = brx * 0.66, nry = bry * 0.7, w = brx * 0.032;
  const strands = [];
  for (let i = 0; i < 40; i++){
    const a = rnd(0, TAU), r = Math.sqrt(rng()) * 0.85;
    let x = nx + Math.cos(a) * nrx * r, y = ny + Math.sin(a) * nry * r, h = rnd(0, TAU);
    const pts = [[x, y]], n = 7 + Math.floor(rnd(0, 5)), step = brx * 0.11, curv = rnd(-0.5, 0.5);
    for (let k = 0; k < n; k++){
      h += curv + rnd(-0.35, 0.35);
      x += Math.cos(h) * step; y += Math.sin(h) * step * 0.62;
      const u = (x - nx) / nrx, v = (y - ny) / nry, d = Math.hypot(u, v);
      if (d > 0.97){ h = Math.atan2((ny - y) * nrx / nry, nx - x) + rnd(-0.6, 0.6); x = nx + u / d * nrx * 0.97; y = ny + v / d * nry * 0.97; }
      pts.push([x, y]);
    }
    strands.push(pts);
  }
  const path = (pts) => { g.beginPath(); g.moveTo(pts[0][0], pts[0][1]); for (let k = 1; k < pts.length - 1; k++){ g.quadraticCurveTo(pts[k][0], pts[k][1], (pts[k][0] + pts[k + 1][0]) / 2, (pts[k][1] + pts[k + 1][1]) / 2); } const l = pts[pts.length - 1]; g.lineTo(l[0], l[1]); };
  softDisc(g, nx, ny + bry * 0.08, nrx * 1.05, nry * 1.05, [[0, 'rgba(70,30,5,0.45)'], [1, 'rgba(70,30,5,0)']]);
  strands.forEach((pts, i) => {
    const t = i / strands.length;
    g.lineWidth = w + 2.2; g.strokeStyle = `rgba(90,50,10,${0.35 + t * 0.3})`; path(pts); g.stroke();
    g.lineWidth = w; g.strokeStyle = `hsl(43,${60 + t * 15}%,${58 + t * 18}%)`; path(pts); g.stroke();
    g.lineWidth = w * 0.32; g.strokeStyle = `rgba(255,248,225,${0.25 + t * 0.35})`;
    g.save(); g.translate(-w * 0.18, -w * 0.22); path(pts); g.stroke(); g.restore();
  });
}

function tofu(g, x, y, s, rot){
  g.save(); g.translate(x, y);
  const c = Math.cos(rot), sn = Math.sin(rot), hgt = s * 0.55;
  const q = [[-1, -1], [1, -1], [1, 1], [-1, 1]].map(([a, b]) => [(a * c - b * sn) * s / 2, (a * sn + b * c) * s / 4]);
  for (let i = 0; i < 4; i++){
    const p = q[i], n = q[(i + 1) % 4], ox = n[1] - p[1], oy = -(n[0] - p[0]);
    if (oy <= 0) continue;
    const m = Math.hypot(ox, oy), lit = clamp(0.58 - ox / m * 0.22 + oy / m * 0.08, 0.3, 0.85);
    g.beginPath(); g.moveTo(p[0], p[1]); g.lineTo(n[0], n[1]); g.lineTo(n[0], n[1] + hgt); g.lineTo(p[0], p[1] + hgt); g.closePath();
    const grd = g.createLinearGradient(0, 0, 0, hgt); grd.addColorStop(0, `hsl(42,45%,${lit * 100}%)`); grd.addColorStop(1, `hsl(38,45%,${lit * 80}%)`);
    g.fillStyle = grd; g.fill(); g.strokeStyle = 'rgba(120,80,30,0.5)'; g.lineWidth = 0.8; g.stroke();
    g.fillStyle = 'rgba(170,110,40,0.35)';
    for (let k = 0; k < 3; k++){ const t = rnd(0.1, 0.9); g.beginPath(); g.ellipse(lerp(p[0], n[0], t), lerp(p[1], n[1], t) + rnd(hgt * 0.2, hgt * 0.8), s * 0.09, s * 0.05, rnd(0, 3), 0, TAU); g.fill(); }
  }
  g.beginPath(); q.forEach((p, i) => i ? g.lineTo(p[0], p[1]) : g.moveTo(p[0], p[1])); g.closePath();
  const grd = g.createLinearGradient(-s / 2, -s / 4, s / 2, s / 4); grd.addColorStop(0, '#fcf5e4'); grd.addColorStop(1, '#eadcb8');
  g.fillStyle = grd; g.fill(); g.strokeStyle = 'rgba(120,80,30,0.45)'; g.lineWidth = 0.8; g.stroke();
  g.fillStyle = 'rgba(200,140,60,0.30)';
  for (let k = 0; k < 4; k++){ g.beginPath(); g.ellipse(rnd(-s * 0.3, s * 0.3), rnd(-s * 0.15, s * 0.15), s * 0.12, s * 0.05, rnd(0, 3), 0, TAU); g.fill(); }
  g.restore();
}

function corn(g, [x, y], ex, ey){
  const kr = S.brx * 0.026;
